package io.github.muntashirakon.adb;import java.security.*;import java.security.cert.Certificate;import java.util.concurrent.*;
public abstract class AbsAdbConnectionManager {public static volatile String lastCommand="";public static volatile int connects,launches,disconnects;public static volatile boolean failConnect,noHeartbeat;public static volatile Runnable heartbeat=()->{};public static volatile CountDownLatch entered,release;boolean connected;
 protected abstract PrivateKey getPrivateKey();protected abstract Certificate getCertificate();protected abstract String getDeviceName();public void setApi(int api){}public void setHostAddress(String h){}public void setTimeout(long t,TimeUnit u){}public boolean pair(String h,int p,String c){return true;}public boolean isConnected(){return connected;}
 public boolean connect(String host,int port)throws Exception {connects++;if(entered!=null)entered.countDown();if(release!=null&&!release.await(5,TimeUnit.SECONDS))throw new RuntimeException("test latch timeout");connected=!failConnect;return connected;}
 public AdbStream openStream(String command){lastCommand=command;if(!command.contains("ru.folio.penbridge.SharedPenBridge"))throw new AssertionError("wrong helper");launches++;if(!noHeartbeat)heartbeat.run();return new AdbStream();}public void disconnect(){disconnects++;connected=false;}}
